172	    private String prepareObjectName(@NotNull SQLDbObjectCompletionItem<?> objectCompletionItem) {
173	        String name;
174	        if (objectCompletionItem.resolvedContext != null) {
175	            String accomplishedPart;
176	            if (objectCompletionItem.resolvedContext.preventFullName()) {
177	                accomplishedPart = this.convertCaseIfNeeded(DBUtils.getQuotedIdentifier(objectCompletionItem.getObject()));
178	            } else {
179	                accomplishedPart = this.prepareQualifiedName(objectCompletionItem.object, objectCompletionItem.resolvedContext.object());
180	            }
181	            name = objectCompletionItem.resolvedContext.string() + this.convertCaseIfNeeded(accomplishedPart);
182	        } else {
183	            name = this.prepareObjectName(objectCompletionItem.object);
184	        }
185	        return name;
186	    }
