188	    @NotNull
189	    private <T extends DBSObject> String prepareObjectName(@NotNull DBSObject namedObject) {
190	        boolean forceFullName = !this.objectBelongsToTheActiveContext(namedObject) || this.activeContextHasConflictingName(namedObject);
191	
192	        String shortName = DBUtils.getQuotedIdentifier(namedObject);
193	        String name;
194	        if (this.request.getContext().isUseShortNames() && !forceFullName) {
195	            name = shortName;
196	        } else if (this.request.getContext().isUseFQNames() || forceFullName) {
197	            name = DBUtils.getObjectFullName(namedObject, DBPEvaluationContext.DML);
198	            if (name.equals(shortName)) { // catalog name is not being included in full name for some reason sometimes
199	                name = this.prepareQualifiedName(namedObject, null);
200	            }
201	        } else {
202	            name = shortName;
203	        }
204	        return this.convertCaseIfNeeded(name);
205	    }
206	
207	    private boolean objectBelongsToTheActiveContext(@NotNull DBSObject object) {
208	        return object.getParentObject() instanceof DBSObjectContainer objectContainer &&
209	            this.queryCompletionContext.getExposedContexts().contains(objectContainer);
210	    }
211	
212	    private boolean activeContextHasConflictingName(@NotNull DBSObject object) {
213	        try {
214	            if (this.activeContext != null) {
215	                DBSObject child = activeContext.getChild(this.monitor, object.getName());
216	                return child != null && !child.equals(object);
217	            }
218	        } catch (DBException e) {
219	            log.debug("Failed to validate database object completion name ambiguity", e);
220	        }
221	        return false;
222	    }
