224	    private String prepareQualifiedName(@NotNull DBSObject object, DBSObject knownSubroot) {
225	        List<String> parts = SQLQueryCompletionItem.prepareQualifiedNameParts(object, knownSubroot);
226	        return String.join(this.structSeparator, parts);
227	    }
