229	    private String prepareQualifiedName(@NotNull List<String> nameParts) {
230	        DBPDataSource dataSource = this.request.getContext().getDataSource();
231	        return nameParts.stream()
232	            .map(s -> DBUtils.getQuotedIdentifier(dataSource, s))
233	            .collect(Collectors.joining(this.structSeparator));
234	    }
