252	    @NotNull
253	    @Override
254	    public String visitProcedure(@NotNull SQLProcedureCompletionItem procedure) {
255	        String name = this.prepareObjectName(procedure);
256	
257	        try {
258	            String text;
259	            Collection<? extends DBSProcedureParameter> parameters = procedure.getObject().getParameters(monitor);
260	            if (!CommonUtils.isEmpty(parameters)) {
261	                StringBuilder sb = new StringBuilder();
262	                sb.append(name).append("(");
263	                int index = 0;
264	                for (DBSProcedureParameter param : parameters) {
265	                    if (param.getParameterKind().isInput()) {
266	                        if (index++ > 0) {
267	                            sb.append(", ");
268	                        }
269	                        sb.append(":").append(param.getName());
270	                    }
271	                }
272	                sb.append(")");
273	                text = sb.toString();
274	            } else {
275	                text = name + "()";
276	            }
277	            return text;
278	        } catch (DBException e) {
279	            log.error("Failed to obtain procedure parameters info", e);
280	            return name;
281	        }
282	    }
